  "documentation": {
    "content": "Alert fires when the Vertex AI custom job 'flakycdcd16' logs an error / fails. The flakycdcd16 job (error code ERR-269536) is expected to fail; this alert surfaces that failure.",
    "mimeType": "text/markdown"
  },
  "combiner": "OR",
  "conditions": [
    {
      "displayName": "flakycdcd16 custom job failure log",
      "conditionMatchedLog": {
        "filter": "resource.type=\"aiplatform.googleapis.com/CustomJob\" AND severity>=ERROR"
      }
    }
  ],
  "alertStrategy": {
    "notificationRateLimit": {
      "period": "3600s"
    }
  },
  "enabled": true
}

